const DATABASE_NAME = 'tavern-helper-new-liuzhuang-avatars';
const STORE_NAME = 'avatars';

function currentScope(): string {
  const characterId = Number.parseInt(SillyTavern.characterId, 10);
  const character = String(
    SillyTavern.characters?.[characterId]?.avatar ?? SillyTavern.name2 ?? SillyTavern.characterId ?? 'new-liuzhuang',
  );
  const chat = String(SillyTavern.getCurrentChatId() ?? 'unknown-chat');
  return `${character}::${chat}`;
}

function openDatabase(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DATABASE_NAME, 1);
    request.onupgradeneeded = () => request.result.createObjectStore(STORE_NAME);
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function key(roleId: number): string {
  return `${currentScope()}::${roleId}`;
}

function estimateDataUrlBytes(dataUrl: string): number {
  const payload = dataUrl.slice(dataUrl.indexOf(',') + 1);
  return Math.ceil((payload.length * 3) / 4);
}

export async function readAvatar(roleId: number): Promise<string | null> {
  const database = await openDatabase();
  return new Promise((resolve, reject) => {
    const request = database.transaction(STORE_NAME, 'readonly').objectStore(STORE_NAME).get(key(roleId));
    request.onsuccess = () => {
      database.close();
      resolve(typeof request.result === 'string' ? request.result : null);
    };
    request.onerror = () => {
      database.close();
      reject(request.error);
    };
  });
}

export async function saveAvatar(roleId: number, file: File): Promise<string> {
  if (!file.type.startsWith('image/')) throw new Error('请选择图片文件');
  if (file.size > 5 * 1024 * 1024) throw new Error('头像图片不能超过5MB');
  const source = await new Promise<string>((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result));
    reader.onerror = () => reject(reader.error);
    reader.readAsDataURL(file);
  });
  const dataUrl = await new Promise<string>((resolve, reject) => {
    const image = new Image();
    image.onload = () => {
      const scale = Math.min(1, 1024 / Math.max(image.naturalWidth, image.naturalHeight));
      const canvas = document.createElement('canvas');
      canvas.width = Math.max(1, Math.round(image.naturalWidth * scale));
      canvas.height = Math.max(1, Math.round(image.naturalHeight * scale));
      canvas.getContext('2d')?.drawImage(image, 0, 0, canvas.width, canvas.height);
      resolve(canvas.toDataURL('image/webp', 0.86));
    };
    image.onerror = () => reject(new Error('头像图片无法解码'));
    image.src = source;
  });
  if (estimateDataUrlBytes(dataUrl) > 2.5 * 1024 * 1024) throw new Error('压缩后的头像仍超过2.5MB');

  const database = await openDatabase();
  await new Promise<void>((resolve, reject) => {
    const request = database.transaction(STORE_NAME, 'readwrite').objectStore(STORE_NAME).put(dataUrl, key(roleId));
    request.onsuccess = () => {
      database.close();
      resolve();
    };
    request.onerror = () => {
      database.close();
      reject(request.error);
    };
  });
  return dataUrl;
}

export async function deleteAvatar(roleId: number): Promise<void> {
  const database = await openDatabase();
  await new Promise<void>((resolve, reject) => {
    const request = database.transaction(STORE_NAME, 'readwrite').objectStore(STORE_NAME).delete(key(roleId));
    request.onsuccess = () => {
      database.close();
      resolve();
    };
    request.onerror = () => {
      database.close();
      reject(request.error);
    };
  });
}
