const STORAGE_KEY = 'tavern_helper_display_settings_新世纪刘庄';
const SettingsSchema = z
    .object({
    themeMode: z.enum(['midnight-sky', 'night-lantern', 'warm-paper']).prefault('midnight-sky'),
    fontSize: z.coerce.number().transform(value => _.clamp(Math.round(value), 14, 24)).prefault(17),
    lineHeight: z.enum(['compact', 'normal', 'relaxed', 'loose']).prefault('normal'),
    fontFamily: z.enum(['serif', 'sans', 'kaiti', 'songti']).prefault('serif'),
})
    .prefault({});
function storage() {
    try {
        return window.parent.localStorage;
    }
    catch {
        return window.localStorage;
    }
}
export const useSettingsStore = defineStore('new-liuzhuang-settings', () => {
    const saved = (() => {
        try {
            return SettingsSchema.parse(JSON.parse(storage().getItem(STORAGE_KEY) ?? '{}'));
        }
        catch {
            return SettingsSchema.parse({});
        }
    })();
    const themeMode = ref(saved.themeMode);
    const fontSize = ref(saved.fontSize);
    const lineHeight = ref(saved.lineHeight);
    const fontFamily = ref(saved.fontFamily);
    watch([themeMode, fontSize, lineHeight, fontFamily], ([tm, fs, lh, ff]) => {
        try {
            storage().setItem(STORAGE_KEY, JSON.stringify({ themeMode: tm, fontSize: fs, lineHeight: lh, fontFamily: ff }));
        }
        catch {
            toastr.warning('显示设置已临时应用，但浏览器拒绝保存');
        }
    }, { immediate: true });
    function reset() {
        const defaults = SettingsSchema.parse({});
        themeMode.value = defaults.themeMode;
        fontSize.value = defaults.fontSize;
        lineHeight.value = defaults.lineHeight;
        fontFamily.value = defaults.fontFamily;
    }
    return { themeMode, fontSize, lineHeight, fontFamily, reset };
});
