import { Schema } from '../../schema';
export function readLatestValidStatData() {
    try {
        for (let id = getLastMessageId(); id >= 0; id--) {
            const raw = _.get(Mvu.getMvuData({ type: 'message', message_id: id }), 'stat_data') ??
                _.get(getVariables({ type: 'message', message_id: id }), 'stat_data');
            if (_.isEmpty(raw))
                continue;
            const parsed = Schema.safeParse(raw);
            if (parsed.success)
                return parsed.data;
        }
        const chatRaw = _.get(getVariables({ type: 'chat' }), 'stat_data');
        if (!_.isEmpty(chatRaw)) {
            const parsed = Schema.safeParse(chatRaw);
            if (parsed.success)
                return parsed.data;
        }
    }
    catch (error) {
        console.warn('[新世纪刘庄] 读取最近有效变量失败', error);
    }
    return Schema.parse({});
}
export const useDataStore = defineStore('mvu_data.new_liuzhuang', () => {
    const data = ref(readLatestValidStatData());
    function syncFromRuntime() {
        const next = readLatestValidStatData();
        if (!_.isEqual(data.value, next))
            data.value = next;
    }
    useIntervalFn(syncFromRuntime, 1200);
    eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, syncFromRuntime);
    eventOn(tavern_events.MESSAGE_RECEIVED, syncFromRuntime);
    eventOn(tavern_events.MESSAGE_UPDATED, syncFromRuntime);
    eventOn(tavern_events.MESSAGE_EDITED, syncFromRuntime);
    eventOn(tavern_events.MESSAGE_DELETED, syncFromRuntime);
    eventOn(tavern_events.MESSAGE_SWIPED, syncFromRuntime);
    eventOn(tavern_events.GENERATION_ENDED, syncFromRuntime);
    return { data, syncFromRuntime };
});
