import { klona } from 'klona';
import { jsonrepair } from 'jsonrepair';
import { Schema } from '../../schema';
let queue = Promise.resolve();
// 品质由前端独立抽签；时代与场景只参与决定商品形态，不参与决定品质。
const SHOP_QUALITY_PROBABILITIES = [
    { quality: '普通', probability: 55 },
    { quality: '优秀', probability: 27 },
    { quality: '稀有', probability: 12 },
    { quality: '史诗', probability: 5 },
    { quality: '传说', probability: 1 },
];
const GeneratedShopCatalog = z.object({
    商品: z
        .array(z.object({
        名称: z.string().min(1),
        分类: z.string().min(1),
        品质: z.enum(['普通', '优秀', '稀有', '史诗', '传说']),
        价格: z.coerce.number().transform(value => Math.max(0, Number(value.toFixed(2)))),
        库存: z.coerce.number().transform(value => Math.max(1, Math.floor(value))),
        可使用: z.boolean(),
        使用后消耗: z.boolean(),
        效果: z.string(),
        说明: z.string(),
    }))
        .min(6)
        .max(10)
        .refine(items => _.uniq(items.map(item => item.名称)).length === items.length, '商品名称不得重复'),
});
function normalizeGeneratedShopQuality(value) {
    const quality = String(value ?? '普通').trim();
    const aliases = {
        普通: '普通',
        良好: '优秀',
        优良: '优秀',
        优秀: '优秀',
        精品: '优秀',
        珍稀: '稀有',
        稀有: '稀有',
        史诗: '史诗',
        传奇: '传说',
        传说: '传说',
    };
    return aliases[quality] ?? value;
}
function normalizeGeneratedShopPayload(input) {
    if (!_.isPlainObject(input))
        return input;
    const payload = input;
    const chineseItems = Array.isArray(payload.商品) ? payload.商品 : null;
    const englishItems = Array.isArray(payload.items) ? payload.items : null;
    const items = chineseItems ?? englishItems;
    if (!items)
        return input;
    if (!chineseItems)
        console.info('[新世纪刘庄] 商店接口未遵循JSON Schema，已兼容转换英文货架字段');
    return {
        商品: items.map((value, index) => {
            const item = _.isPlainObject(value) ? value : {};
            const 名称 = String(item.名称 ?? item.name ?? `未命名商品${index + 1}`).trim();
            const 分类 = String(item.分类 ?? item.category ?? '杂物').trim();
            const 说明 = [item.说明 ?? item.spec, chineseItems ? undefined : item.description]
                .filter(value => typeof value === 'string' && value.trim())
                .join('；');
            const skillLike = /教材|手册|图纸|技能|book|manual/i.test(`${名称} ${分类}`);
            const consumableLike = skillLike || /食品|药|蚊香|消杀|耗材|种子|肥料|农药/.test(`${名称} ${分类}`);
            return {
                名称,
                分类,
                品质: normalizeGeneratedShopQuality(item.品质 ?? item.quality),
                价格: item.价格 ?? item.price ?? item.price_cny ?? 0,
                库存: item.库存 ?? item.stock ?? 1,
                可使用: typeof item.可使用 === 'boolean' ? item.可使用 : skillLike || consumableLike,
                使用后消耗: typeof item.使用后消耗 === 'boolean' ? item.使用后消耗 : consumableLike,
                效果: String(item.效果 ?? item.effect ?? item.description ?? ''),
                说明,
            };
        }),
    };
}
function parseGeneratedShopCatalog(raw) {
    let source = raw.trim();
    const fenced = /```(?:json)?\s*([\s\S]*?)```/i.exec(source)?.[1];
    if (fenced)
        source = fenced.trim();
    const objectStart = source.indexOf('{');
    const objectEnd = source.lastIndexOf('}');
    if (objectStart >= 0 && objectEnd > objectStart)
        source = source.slice(objectStart, objectEnd + 1);
    try {
        return GeneratedShopCatalog.parse(normalizeGeneratedShopPayload(JSON.parse(source)));
    }
    catch {
        try {
            return GeneratedShopCatalog.parse(normalizeGeneratedShopPayload(JSON.parse(jsonrepair(source))));
        }
        catch (secondError) {
            console.error('[新世纪刘庄] 商店返回数据校验失败', secondError);
            throw new Error('商店返回内容无法解析为有效商品数据', { cause: secondError });
        }
    }
}
function runtimeGenerating() {
    const tavern = SillyTavern;
    return Boolean(tavern.isGenerating || tavern.getContext?.()?.isGenerating);
}
function compactText(value, maxLength = 48) {
    const text = String(value ?? '')
        .replace(/\s+/g, ' ')
        .trim();
    return text.length > maxLength ? `${text.slice(0, maxLength)}…` : text;
}
function randomInteger(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
}
function rollShopQuality() {
    const roll = Math.random() * 100;
    let cumulative = 0;
    for (const entry of SHOP_QUALITY_PROBABILITIES) {
        cumulative += entry.probability;
        if (roll < cumulative)
            return entry.quality;
    }
    return '普通';
}
function rollShopQualityPlan(count) {
    return Array.from({ length: count }, () => rollShopQuality());
}
function summarizeShopContext(data) {
    const player = data.玩家信息;
    const world = data.世界信息;
    const village = data.村庄状态;
    const skills = Object.entries(player.技能)
        .slice(0, 8)
        .map(([name, skill]) => `${name}(等级${skill.等级})`)
        .join('、');
    const inventory = Object.keys(player.物品栏).slice(0, 12).join('、');
    const projects = Object.entries(village.项目)
        .filter(([, project]) => !['完成', '搁置'].includes(project.状态))
        .slice(0, 6)
        .map(([name, project]) => `${name}[${project.状态}；需求：${compactText(project.需求 || '未明确')}；下一步：${compactText(project.下一步 || '未明确')}]`)
        .join('；');
    const facilities = Object.entries(village.设施)
        .slice(0, 8)
        .map(([name, facility]) => `${name}[${compactText(facility.状态 || facility.功能 || '状态未明')}]`)
        .join('；');
    const priorShelf = Object.keys(data.系统商店.商品).slice(0, 10).join('、');
    return [
        `玩家：${player.姓名 || '未说明'}，身份：${compactText(player.身份)}，现金：${player.现金}元，当前状态：${compactText(player.当前状态, 72)}`,
        `时间与环境：${world.日期时间.年}年${world.日期时间.月}月${world.日期时间.日}日${world.时段}，${compactText(world.天气)}，农时：${compactText(world.农时)}，地点：${compactText(world.玩家当前地点)}`,
        `已有技能：${skills || '无明确技能'}`,
        `已有物品：${inventory || '无'}`,
        `在办项目：${projects || '无'}`,
        `相关设施：${facilities || '无明确设施'}`,
        `上一轮货架：${priorShelf || '无；这是首次生成'}`,
    ].join('\n');
}
function enqueue(operation) {
    const result = queue.then(operation, operation);
    queue = result.then(() => undefined, () => undefined);
    return result;
}
function latestState() {
    const messageId = getLastMessageId();
    if (messageId < 0)
        throw new Error('当前聊天没有可写入楼层');
    const target = { type: 'message', message_id: messageId };
    for (let id = messageId; id >= 0; id--) {
        const raw = _.get(Mvu.getMvuData({ type: 'message', message_id: id }), 'stat_data');
        if (_.isEmpty(raw))
            continue;
        const parsed = Schema.safeParse(raw);
        if (parsed.success) {
            return {
                target,
                mvu: klona(Mvu.getMvuData(target)),
                variables: klona(getVariables(target)),
                data: parsed.data,
            };
        }
    }
    throw new Error('找不到可用的MVU状态');
}
async function write(state, nextInput) {
    const next = Schema.parse(nextInput);
    const mvu = klona(state.mvu);
    const variables = klona(state.variables);
    _.set(mvu, 'stat_data', next);
    _.set(variables, 'stat_data', next);
    await Mvu.replaceMvuData(mvu, state.target);
    replaceVariables(variables, state.target);
}
export function savePlayerProfile(profile) {
    return enqueue(async () => {
        if (runtimeGenerating())
            throw new Error('生成期间暂不能保存档案');
        const state = latestState();
        const next = klona(state.data);
        Object.assign(next.玩家信息, profile);
        next.玩家信息.当前状态 = '已在刘庄村口完成基本介绍，准备重新进入村中生活';
        next.系统状态.初始化状态 = '进行中';
        await write(state, next);
    });
}
