export function purchaseProduct(name) {
    return enqueue(async () => {
        if (runtimeGenerating())
            throw new Error('生成期间暂不能购买商品');
        const state = latestState();
        const next = klona(state.data);
        const product = next.系统商店.商品[name];
        if (!product || product.库存 <= 0)
            throw new Error('商品已经售罄');
        if (next.玩家信息.现金 < product.价格)
            throw new Error('现金不足');
        next.玩家信息.现金 -= product.价格;
        product.库存 -= 1;
        const owned = next.玩家信息.物品栏[name];
        if (owned) {
            owned.数量 += 1;
        }
        else {
            next.玩家信息.物品栏[name] = {
                分类: product.分类,
                品质: product.品质,
                数量: 1,
                可使用: product.可使用,
                使用后消耗: product.使用后消耗,
                效果: product.效果,
                来源: '系统商店购买',
            };
        }
        next.系统商店.最近交易 = `购买${name}，支出${product.价格}元`;
        await write(state, next);
        return next.系统商店.最近交易;
    });
}
export function requestShopRefresh() {
    return enqueue(async () => {
        if (runtimeGenerating())
            throw new Error('生成期间暂不能刷新商品');
        const state = latestState();
        if (state.data.系统商店._刷新请求)
            return;
        const firstLoad = _.isEmpty(state.data.系统商店.商品);
        if (!firstLoad && state.data.玩家信息.现金 < state.data.系统商店.刷新费用)
            throw new Error('现金不足，无法刷新商品');
        const next = klona(state.data);
        next.系统商店._刷新请求 = true;
        await write(state, next);
    });
}
export function refreshShopIfRequested() {
    return enqueue(async () => {
        const before = latestState();
        if (!before.data.系统商店._刷新请求)
            return null;
        const firstLoad = _.isEmpty(before.data.系统商店.商品);
        const cost = firstLoad ? 0 : before.data.系统商店.刷新费用;
        if (before.data.玩家信息.现金 < cost) {
            const reset = klona(before.data);
            reset.系统商店._刷新请求 = false;
            await write(before, reset);
            throw new Error('现金不足，刷新请求已取消');
        }
        try {
            const shopContext = summarizeShopContext(before.data);
            const itemCount = randomInteger(6, 10);
            const qualityPlan = rollShopQualityPlan(itemCount);
            const qualityPlanText = qualityPlan.map((quality, index) => `${index + 1}号商品=${quality}`).join('，');
            console.info(`[新世纪刘庄] 本轮商店品质抽签：${qualityPlanText}`);
            const result = await generateRaw({
                generation_id: `new-liuzhuang-shop-refresh-${Date.now()}`,
                should_stream: false,
                should_silence: false,
                user_input: [
                    `为2001年苏北刘庄的系统商店随机生成一次全新货架。\n<当前状态>\n${shopContext}\n</当前状态>\n`,
                    `本轮已经独立随机抽出${itemCount}个商品槽位，必须严格生成${itemCount}件互不重名的商品。品质抽签结果依次为：${qualityPlanText}。必须按数组顺序逐项使用，不得根据农村氛围、商品类别或主观判断修改品质。`,
                    '货架主体必须能改变玩家可采取的行动、提高生产或维修效率、补足项目条件、提供技能来源或带来新的发展机会；纯日用品只能少量点缀，不得用牙膏、牙刷、肥皂、调味品和普通食品等相似低价值商品填满货架。',
                    '一部分商品应与当前处境存在联系，另一部分应是合理但意外的未来机会，避免全部迎合当前任务。独特性应来自专业用途、稀缺性、特殊来源、成色或缺陷、组合价值与使用门槛，禁止超自然能力。',
                    '商品的稀缺性、完整度、专业价值、说明与价格必须匹配已经抽中的品质；价格符合2001年购买力并有明显层次，可以少量出现当前现金暂时买不起但值得规划的商品。技能类教材或图纸可以有0至2件，不得固定出现。',
                    '效果要写清它能解决的问题、创造的行动条件、节省的时间或资源、提供的知识来源以及必要限制；说明要体现时代、来源、成色或使用门槛。避免与上一轮同名或功能高度重复，不写剧情或解释，只返回要求的JSON。',
                    'JSON顶层只能有“商品”字段；“商品”必须是数组。每件商品必须且只能使用这些中文字段：名称、分类、品质、价格、库存、可使用、使用后消耗、效果、说明。不得使用items、name、price_cny等英文字段。',
                    '品质只能填写“普通、优秀、稀有、史诗、传说”之一，不得使用“良好、优良、精品、传奇”等近义词。',
                ].join(''),
                ordered_prompts: [
                    {
                        role: 'system',
                        content: '你负责生成写实但具有RPG机会感的2001年苏北乡村系统商店货架。写实不等于琐碎：货架不是普通小卖部清单，大多数商品应带来行动选择、生产价值、知识门槛或发展可能。保持高度随机，不设固定货单，不使用现代技术或超自然功效。',
                    },
                    'user_input',
                ],
                json_schema: {
                    name: 'liuzhuang_shop_catalog',
                    strict: true,
                    value: {
                        type: 'object',
                        additionalProperties: false,
                        properties: {
                            商品: {
                                type: 'array',
                                minItems: itemCount,
                                maxItems: itemCount,
                                items: {
                                    type: 'object',
                                    additionalProperties: false,
                                    properties: {
                                        名称: { type: 'string' },
                                        分类: { type: 'string' },
                                        品质: { type: 'string', enum: ['普通', '优秀', '稀有', '史诗', '传说'] },
                                        价格: { type: 'number', minimum: 0 },
                                        库存: { type: 'integer', minimum: 1 },
                                        可使用: { type: 'boolean' },
                                        使用后消耗: { type: 'boolean' },
                                        效果: { type: 'string' },
                                        说明: { type: 'string' },
                                    },
                                    required: ['名称', '分类', '品质', '价格', '库存', '可使用', '使用后消耗', '效果', '说明'],
                                },
                            },
                        },
                        required: ['商品'],
                    },
                },
            });
            const raw = typeof result === 'string' ? result : result.content;
            const parsed = parseGeneratedShopCatalog(raw);
            const generated = {
                商品: parsed.商品.map((item, index) => ({
                    ...item,
                    品质: qualityPlan[index] ?? rollShopQuality(),
                })),
            };
            const state = latestState();
            if (!state.data.系统商店._刷新请求)
                return null;
            const currentFirstLoad = _.isEmpty(state.data.系统商店.商品);
            const currentCost = currentFirstLoad ? 0 : state.data.系统商店.刷新费用;
            if (state.data.玩家信息.现金 < currentCost)
                throw new Error('刷新期间现金发生变化，余额已不足');
            const next = klona(state.data);
            next.玩家信息.现金 -= currentCost;
            next.系统商店.商品 = Object.fromEntries(generated.商品.map(({ 名称, ...product }) => [名称, product]));
            next.系统商店._刷新请求 = false;
            next.系统商店.最近交易 = currentFirstLoad
                ? `首次生成货架，共${generated.商品.length}件商品`
                : `刷新货架，支出${currentCost}元，共${generated.商品.length}件商品`;
            await write(state, next);
            return next.系统商店.最近交易;
        }
        catch (error) {
            const state = latestState();
            if (state.data.系统商店._刷新请求) {
                const reset = klona(state.data);
                reset.系统商店._刷新请求 = false;
                await write(state, reset);
            }
            throw error;
        }
    });
}
