                await createChatMessages([{ role: 'user', message: value }], { insert_before: 'end', refresh: 'affected' });
                let latest = getChatMessages(-1, { role: 'all' })[0];
                let retries = 0;
                while ((!latest || latest.message_id <= old || latest.role !== 'user') && retries < 15) {
                    await new Promise(resolve => setTimeout(resolve, 80));
