import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';
import { waitUntil } from 'async-wait-until';
import { disposePinia } from 'pinia';
import { reloadOnChatChange } from '@util/script';
import { mountStreamingMessages } from '@util/streaming';
import { Schema } from '../../schema';
import App from './App.vue';
import './style.scss';
const PARENT_STYLE_ID = 'new-liuzhuang-floor-style';
const HOST_PREFIX = 'new-liuzhuang-floor';
const HOST_FLOOR_CLASS = 'th-same-layer-host';
let selectedHostMessageId = null;
let lastStatDataError = '';
let releaseHostMessage = null;
function ensureFloorStyle() {
    const hostDoc = window.parent?.document ?? document;
    const viewportHeight = Math.max(620, Math.min(900, (window.parent?.innerHeight ?? 900) - 32));
    const css = [
        'iframe[id^="' + HOST_PREFIX + '-"] {',
        '  width: 100% !important;',
        '  min-width: 100% !important;',
        '  height: ' + viewportHeight + 'px !important;',
        '  min-height: ' + viewportHeight + 'px !important;',
        '  border: none !important;',
        '  display: block !important;',
        '}',
        'iframe[id^="' + HOST_PREFIX + '-"]:fullscreen,',
        'iframe[id^="' + HOST_PREFIX + '-"]:-webkit-full-screen {',
        '  width: 100% !important;',
        '  height: 100% !important;',
        '  min-width: 0 !important;',
        '  min-height: 0 !important;',
        '  max-width: none !important;',
        '  max-height: none !important;',
        '  border: none !important;',
        '  background: #071018 !important;',
        '}',
        '.mes_streaming:has(iframe[id^="' + HOST_PREFIX + '-"]) {',
        '  width: 100% !important;',
        '  min-height: ' + viewportHeight + 'px !important;',
        '  padding: 0 !important;',
        '}',
    ].join('\n');
    let $style = $('#' + PARENT_STYLE_ID, hostDoc);
    if ($style.length === 0)
        $style = $('<style>').attr('id', PARENT_STYLE_ID).appendTo(hostDoc.head);
    if ($style.text() !== css)
        $style.text(css);
}
function enableHostFullscreen(host) {
    if (host?.tagName !== 'IFRAME')
        return;
    host.setAttribute('allowfullscreen', '');
    const allow = host.getAttribute('allow')?.trim() ?? '';
    if (!/(^|;)\s*fullscreen(?:\s|;|$)/i.test(allow)) {
        host.setAttribute('allow', [allow, 'fullscreen'].filter(Boolean).join('; '));
    }
}
function selectHostFloor($floor, messageId) {
    const previousHostMessageId = selectedHostMessageId;
    if (previousHostMessageId === messageId) {
        $floor.addClass(HOST_FLOOR_CLASS);
        return messageId;
    }
    selectedHostMessageId = messageId;
    $('#chat .mes').removeClass(HOST_FLOOR_CLASS);
    $floor.addClass(HOST_FLOOR_CLASS);
    if (previousHostMessageId !== null && previousHostMessageId !== messageId) {
        setTimeout(() => void releaseHostMessage?.(previousHostMessageId), 0);
    }
    return messageId;
}
function isAssistantMessageElement(_index, element) {
    const $element = $(element);
    const isUser = $element.attr('is_user') === 'true' || $element.hasClass('user') || $element.hasClass('is_user');
    const isSystem = $element.attr('is_system') === 'true' || $element.hasClass('system') || $element.hasClass('is_system');
    return !isUser && !isSystem;
}
function resolveHostMessageId() {
    const $message0 = $("#chat .mes[mesid='0']").first();
    if ($message0.length > 0)
        return selectHostFloor($message0, 0);
    if (selectedHostMessageId !== null) {
        const $selected = $("#chat .mes[mesid='" + selectedHostMessageId + "']");
        if ($selected.length > 0) {
            $selected.addClass(HOST_FLOOR_CLASS);
            return selectedHostMessageId;
        }
    }
    const $fallback = $('#chat .mes').filter(isAssistantMessageElement).first();
    const messageId = Number($fallback.attr('mesid'));
    if (!Number.isInteger(messageId) || messageId < 0) {
        selectedHostMessageId = null;
        return null;
    }
    if (messageId !== 0) {
        console.info('[新世纪刘庄] 第0层尚未载入，界面临时挂载到当前可见的第' + messageId + '层');
    }
    return selectHostFloor($fallback, messageId);
}
function readAvailableStatData() {
    const latest = _.get(getVariables({ type: 'message', message_id: -1 }), 'stat_data');
    const latestParsed = Schema.safeParse(latest);
    if (!_.isEmpty(latest) && latestParsed.success)
        return latestParsed.data;
    if (!_.isEmpty(latest) && !latestParsed.success) {
        const detail = z.prettifyError(latestParsed.error);
        if (detail !== lastStatDataError) {
            lastStatDataError = detail;
            console.warn('[新世纪刘庄] 最新楼层变量无效，将尝试恢复历史状态：\n' + detail);
        }
    }
    for (let depth = -2;; depth--) {
        try {
            const previous = _.get(getVariables({ type: 'message', message_id: depth }), 'stat_data');
            const parsed = Schema.safeParse(previous);
            if (!_.isEmpty(previous) && parsed.success)
                return parsed.data;
        }
        catch {
            break;
        }
    }
    const chatData = _.get(getVariables({ type: 'chat' }), 'stat_data');
    const chatParsed = Schema.safeParse(chatData);
    return _.isEmpty(chatData) || !chatParsed.success ? undefined : chatParsed.data;
}
function ensureLatestStatData() {
    const available = readAvailableStatData();
    if (_.isEmpty(available))
        return false;
    const latestOption = { type: 'message', message_id: -1 };
    const latest = _.get(getVariables(latestOption), 'stat_data');
    const latestParsed = Schema.safeParse(latest);
    const normalized = Schema.parse(available);
    if (_.isEmpty(latest) || !latestParsed.success || !_.isEqual(latest, normalized)) {
        updateVariablesWith(variables => _.set(variables, 'stat_data', normalized), latestOption);
        console.info('[新世纪刘庄] 最新楼层变量已继承并规范化');
    }
    return true;
}
async function init() {
    await waitGlobalInitialized('Mvu');
    registerMvuSchema(Schema);
    await waitUntil(() => ensureLatestStatData());
    ensureFloorStyle();
    const { unmount, renderMessage } = mountStreamingMessages(() => {
        const pinia = createPinia();
        const app = createApp(App).use(pinia);
        const originalUnmount = app.unmount.bind(app);
        app.unmount = () => {
            originalUnmount();
            disposePinia(pinia);
        };
        return app;
    }, {
        host: 'iframe',
        prefix: HOST_PREFIX,
        emit_rerender_event: false,
        filter: messageId => messageId === resolveHostMessageId(),
    });
    const reloadListener = reloadOnChatChange();
    releaseHostMessage = renderMessage;
    const ensureHostMounted = async () => {
        ensureFloorStyle();
        const messageId = resolveHostMessageId();
        if (messageId === null)
            return;
        const hostDoc = window.parent?.document ?? document;
        const host = hostDoc.getElementById(HOST_PREFIX + '-' + messageId);
        enableHostFullscreen(host);
        if (host?.closest('.mes')?.getAttribute('mesid') === String(messageId))
            return;
        await renderMessage(messageId);
        enableHostFullscreen(hostDoc.getElementById(HOST_PREFIX + '-' + messageId));
    };
    const hostRecoveryTimer = setInterval(errorCatched(ensureHostMounted), 500);
    setTimeout(errorCatched(ensureHostMounted), 300);
    $(window).on('pagehide', () => {
        clearInterval(hostRecoveryTimer);
        releaseHostMessage = null;
        reloadListener.stop();
        unmount();
        $('#' + PARENT_STYLE_ID, window.parent?.document ?? document).remove();
        $('#chat .mes').removeClass(HOST_FLOOR_CLASS);
    });
    console.info('[新世纪刘庄] 流式乡村界面已挂载到第' + (resolveHostMessageId() ?? '待定') + '层');
}
$(() => {
    errorCatched(init)();
});
