import type { DialogueSegment } from './types';

export type DialogueDisplayContext = {
  role: 'user' | 'assistant';
  depth: number;
  validRoleIds?: readonly number[];
};

const UPDATE_PATTERN = /<update(?:variable)?>[\s\S]*?(?:<\/update(?:variable)?>|$)/gi;
const COMPLETE_DIALOGUE =
  /<CharacterDialogue\b(?=[^>]*\brole_id\s*=\s*["']?\d+["']?)([^>]*)>([\s\S]*?)<\/CharacterDialogue>/gi;

function unwrapDuplicatedCurlyQuotes(value: string): string {
  let trimmed = value.trim();
  while (
    (trimmed.length >= 4 && trimmed.startsWith('““') && trimmed.endsWith('””')) ||
    (trimmed.length >= 4 && trimmed.startsWith('""') && trimmed.endsWith('""')) ||
    (trimmed.length >= 2 && trimmed.startsWith('"“') && trimmed.endsWith('”"')) ||
    (trimmed.length >= 2 && trimmed.startsWith('“"') && trimmed.endsWith('"”'))
  ) {
    trimmed = trimmed.slice(1, -1).trim();
  }
  return trimmed;
}

function fixDoubleQuotes(text: string): string {
  return text
    .replace(/“{2,}/g, '“')
    .replace(/”{2,}/g, '”')
    .replace(/""+/g, '"')
    .replace(/“"/g, '“')
    .replace(/"”/g, '”')
    .replace(/”"/g, '”')
    .replace(/"“/g, '“');
}

export function sanitizeNarrativeSource(raw: string): string {
  let source = raw
    .replace(UPDATE_PATTERN, '')
    .replace(/<!--\s*new-liuzhuang-assistant-updated\s*-->/gi, '')
    .replace(/<StatusPlaceHolderImpl\s*\/?>/gi, '')
    .replace(/<(?:NewLiuzhuangUI|新世纪刘庄UI)\s*\/?>/gi, '')
    .replace(/^[\s\S]*?<\/konatan_planning~>\s*/i, '')
    .replace(/<konatan_planning~>[\s\S]*?<\/konatan_planning~>/gi, '')
    .replace(/<(think(?:ing)?)\b[^>]*>[\s\S]*?<\/\1\s*>/gi, '')
    .replace(/<(?:think|thinking)\b[^>]*>[\s\S]*$/gi, '')
    .replace(/^\s*补丁应用中[.…]*\s*\n\s*变量初始化完成[。.!！…]*\s*/i, '')
    .replace(/<(current_event|progress|tucao)\b[^>]*>[\s\S]*?<\/\1\s*>/gi, '')
    .replace(/<(?:current_event|progress|tucao)\b[^>]*>[\s\S]*$/gi, '')
    .replace(/\r\n?/g, '\n')
    .trim();
  if (source.startsWith('"') && source.endsWith('"')) {
    try {
      const parsed: unknown = JSON.parse(source);
      if (typeof parsed === 'string') source = parsed;
    } catch {
      // 不是完整 JSON 字符串时保留原正文。
    }
  }
  source = unwrapDuplicatedCurlyQuotes(source);
  source = fixDoubleQuotes(source);
  return source;
}

function cleanNarrative(text: string): string {
  const cleaned = text
    .replace(/<\/?(?:content|contenttext|Stage|Speech)\b[^>]*>/gi, '')
    .replace(/<CharacterDialogue\b[^>]*>/gi, '')
    .replace(/<\/CharacterDialogue>/gi, '')
    .replace(/<WorldSimulatorUI\s*\/?>/gi, '')
    .trim();
  return fixDoubleQuotes(unwrapDuplicatedCurlyQuotes(cleaned));
}

function normalizeSpeech(text: string): string {
  let s = text.trim();
  // 剥除 AI 输出台词外层包裹的各种中英文引号，防止与前端气泡自带的引号发生双重叠加
  while (
    (s.startsWith('“') && s.endsWith('”')) ||
    (s.startsWith('"') && s.endsWith('"')) ||
    (s.startsWith("'") && s.endsWith("'")) ||
    (s.startsWith('『') && s.endsWith('』')) ||
    (s.startsWith('「') && s.endsWith('」'))
  ) {
    s = s.slice(1, -1).trim();
  }
  return fixDoubleQuotes(s);
}

function applyDisplayRegex(raw: string, context?: DialogueDisplayContext): string {
  if (!context) return raw;
  try {
    return formatAsTavernRegexedString(raw, context.role === 'user' ? 'user_input' : 'ai_output', 'display', {
      depth: context.depth,
    });
  } catch (error) {
    console.warn('[新世纪刘庄] 酒馆显示正则执行失败，已降级为原始正文', error);
    return raw;
  }
}

export function parseDialogue(raw: string, context?: DialogueDisplayContext): DialogueSegment[] {
  // 酒馆预设/全局/角色正则必须先看到完整楼层原文。若先拆分或清理标签，
  // 思维链、摘要、吐槽、事件/进度等跨标签状态栏正则将永远无法匹配。
  const source = sanitizeNarrativeSource(applyDisplayRegex(raw, context));
  const segments: DialogueSegment[] = [];
  const validRoleIds = context?.validRoleIds ? new Set(context.validRoleIds) : null;
  let cursor = 0;
  for (const match of source.matchAll(COMPLETE_DIALOGUE)) {
    const index = match.index ?? cursor;
    const before = cleanNarrative(source.slice(cursor, index));
    if (before) segments.push({ type: 'narrative', text: before });
    const body = match[2];
    let rawStage = body.match(/<Stage>([\s\S]*?)<\/Stage>/i)?.[1]?.trim() ?? '';
    let rawSpeech = body.match(/<Speech>([\s\S]*?)<\/Speech>/i)?.[1]?.trim() ?? (rawStage ? '' : cleanNarrative(body));

    // 自动容错：若 AI 误将生图标签 <image> 放入 Stage 或 Speech 内部，自动提取并提权为独立旁白插图
    const extractedImages: string[] = [];
    rawStage = rawStage
      .replace(/<image\b[^>]*>[\s\S]*?<\/image>/gi, img => {
        extractedImages.push(img.trim());
        return '';
      })
      .trim();
    rawSpeech = rawSpeech
      .replace(/<image\b[^>]*>[\s\S]*?<\/image>/gi, img => {
        extractedImages.push(img.trim());
        return '';
      })
      .trim();

    const stage = rawStage;
    const speech = normalizeSpeech(rawSpeech);
    const roleIdText = /\brole_id\s*=\s*["']?(\d+)["']?/i.exec(match[1])?.[1];
    const roleId = roleIdText === undefined ? Number.NaN : Number(roleIdText);
    const roleExists = Number.isSafeInteger(roleId) && roleId >= 0 && (!validRoleIds || validRoleIds.has(roleId));
    if (roleExists) {
      segments.push({ type: 'dialogue', roleId, stage, speech });
    } else {
      const fallback = [stage, speech].filter(Boolean).join('\n\n');
      if (fallback) segments.push({ type: 'narrative', text: fallback });
      console.warn(`[新世纪刘庄] CharacterDialogue 的 role_id=${roleIdText ?? '缺失'} 不存在，已降级为叙事`);
    }
    // 将提取出的生图标签作为独立段落插入，确保图片能通过 Markdown / HTML 正常被酒馆生图插件渲染
    for (const img of extractedImages) {
      segments.push({ type: 'narrative', text: img });
    }
    cursor = index + match[0].length;
  }
  const tailSource = source.slice(cursor);
  const incompleteIndex = tailSource.search(/<CharacterDialogue\b/i);
  const tail = cleanNarrative(incompleteIndex >= 0 ? tailSource.slice(0, incompleteIndex) : tailSource);
  if (tail) segments.push({ type: 'narrative', text: tail });
  return segments.length ? segments : [{ type: 'narrative', text: cleanNarrative(source) }];
}
